function makeSmallestPalindrome(s) {
  const chars = s.split('');
  let left = 0;
  let right = chars.length - 1;

  while (left < right) {
    if (chars[left] !== chars[right]) {
      const smaller = chars[left] < chars[right] ? chars[left] : chars[right];
      chars[left] = smaller;
      chars[right] = smaller;
    }
    left++;
    right--;
  }
  return chars.join('');
}

