function makeSmallestPalindrome(s) {
  // Each mismatched mirror pair needs exactly one change, so one of its two letters must win.
  // Try every way of choosing the winners and keep the smallest palindrome.
  const n = s.length;
  const pairs = [];
  for (let i = 0; i < Math.floor(n / 2); i++) if (s[i] !== s[n - 1 - i]) pairs.push(i);
  let best = null;
  for (let mask = 0; mask < (1 << pairs.length); mask++) {
    const out = s.split('');
    pairs.forEach((i, bit) => {
      const letter = (mask >> bit) & 1 ? s[n - 1 - i] : s[i];
      out[i] = letter;
      out[n - 1 - i] = letter;
    });
    const candidate = out.join('');
    if (best === null || candidate < best) best = candidate;
  }
  return best;
}

