function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? pick(1, 12) : pick(900, 1000);
  const alphabets = ['ab', 'abc', 'xyz', 'abcdefghijklmnopqrstuvwxyz'];
  const letters = alphabets[pick(0, alphabets.length - 1)];
  const chars = [];
  for (let i = 0; i < n; i++) chars.push(letters[pick(0, letters.length - 1)]);
  if (rand() < 0.4) {
    // Start from a palindrome and disturb only a few positions.
    for (let i = 0; i < Math.floor(n / 2); i++) chars[n - 1 - i] = chars[i];
    const changes = pick(0, Math.max(1, Math.floor(n / 4)));
    for (let c = 0; c < changes; c++) chars[pick(0, n - 1)] = letters[pick(0, letters.length - 1)];
  }
  return [chars.join('')];
}
